import {
  Component,
  OnInit,
  OnDestroy,
  ViewChild,
  ElementRef,
} from '@angular/core';
import { ChatService } from '../../../services/chat.service';
import { ChatMessage, ChatRoom } from '../../../models/chat.model';

@Component({
  selector: 'app-admin-chat',
  templateUrl: './admin-chat.component.html',
  styleUrls: ['./admin-chat.component.css'],
})
export class AdminChatComponent implements OnInit, OnDestroy {
  @ViewChild('messageContainer') messageContainer!: ElementRef;

  adminName: string = 'admin';
  selectedCustomer: string = '';
  messages: ChatMessage[] = [];
  newMessage: string = '';
  customers: ChatRoom[] = [];
  filteredCustomers: ChatRoom[] = [];
  isLoading: boolean = false;
  searchTerm: string = '';
  onlineCustomers: string[] = ['John Doe', 'Jane Smith', 'Mike Johnson'];

  constructor(private chatService: ChatService) {}

  ngOnInit(): void {
    this.loadCustomers();
    this.connectToChat();
  }

  loadCustomers(): void {
    this.chatService.getConversations('admin').subscribe({
      next: (conversations) => {
        this.customers = conversations;
        this.filteredCustomers = conversations;
        if (this.customers.length > 0 && !this.selectedCustomer) {
          this.selectedCustomer = this.customers[0].user;
          this.loadChatHistory();
        }
      },
      error: (err) => console.error('Error loading customers:', err),
    });
  }

  connectToChat(): void {
    this.chatService.connect('admin').subscribe({
      next: (message) => {
        if (message.sender === this.selectedCustomer) {
          this.messages.push(message);
          this.scrollToBottom();
          this.playNotification();
        }
        this.loadCustomers();
      },
      error: (err) => console.error('WebSocket error:', err),
    });
  }

  loadChatHistory(): void {
    if (!this.selectedCustomer) return;

    this.isLoading = true;
    this.chatService.getChatHistory('admin', this.selectedCustomer).subscribe({
      next: (messages) => {
        this.messages = messages;
        this.isLoading = false;
        this.scrollToBottom();

        messages.forEach((msg) => {
          if (!msg.isRead && msg.receiver === 'admin') {
            this.chatService.markAsRead(msg.id!).subscribe();
          }
        });
      },
      error: (err) => {
        console.error('Error loading chat history:', err);
        this.isLoading = false;
      },
    });
  }

  sendMessage(): void {
    if (!this.newMessage.trim() || !this.selectedCustomer) return;

    const message: ChatMessage = {
      sender: 'admin',
      receiver: this.selectedCustomer,
      message: this.newMessage,
      messageType: 'TEXT',
      timestamp: new Date(),
      isRead: false,
    };

    this.chatService.sendMessage(message);
    this.messages.push(message);
    this.newMessage = '';
    this.scrollToBottom();
  }

  filterCustomers(): void {
    if (!this.searchTerm) {
      this.filteredCustomers = this.customers;
    } else {
      this.filteredCustomers = this.customers.filter((c) =>
        c.user.toLowerCase().includes(this.searchTerm.toLowerCase()),
      );
    }
  }

  selectCustomer(customer: ChatRoom): void {
    this.selectedCustomer = customer.user;
    this.loadChatHistory();
  }

  isCustomerOnline(customer: string): boolean {
    return this.onlineCustomers.includes(customer);
  }

  playNotification(): void {
    const audio = new Audio('/assets/admin-notification.mp3');
    audio.play().catch((e) => console.log('Audio play failed'));
  }

  scrollToBottom(): void {
    setTimeout(() => {
      if (this.messageContainer) {
        this.messageContainer.nativeElement.scrollTop =
          this.messageContainer.nativeElement.scrollHeight;
      }
    }, 100);
  }

  formatTime(date: Date): string {
    return new Date(date).toLocaleTimeString([], {
      hour: '2-digit',
      minute: '2-digit',
    });
  }

  ngOnDestroy(): void {
    this.chatService.disconnect();
  }
}
